import { createTimelineController } from "@ui-sdk/core/timeline";
var parts = createParts(timeline, {
  root: "div",
  item: "div",
  marker: "div",
  connector: "div",
  time: "time",
  title: "div",
  description: "div"
});
var Timeline = parts.Root;
